const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || undefined });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1920, height: 1080 });
  // serve from output/ like html_to_pptx does
  const http = require('http');
  const path = require('path');
  const fs = require('fs');

  const serveDir = path.resolve('output');
  const server = http.createServer((req, res) => {
    const filePath = path.join(serveDir, decodeURIComponent(req.url.split('?')[0]));
    fs.readFile(filePath, (err, data) => {
      if (err) { res.statusCode = 404; return res.end('not found'); }
      res.end(data);
    });
  });
  await new Promise(r => server.listen(0, '127.0.0.1', r));
  const port = server.address().port;

  await page.goto(`http://127.0.0.1:${port}/presentation.html`, { waitUntil: 'networkidle' });
  const slideCount = await page.$$eval('.slide', els => els.length);
  console.log('slideCount', slideCount);
  // screenshot & sample pixels for first 6 slides
  async function sample(i){
    if(i>1){
      await page.keyboard.press('ArrowRight');
      await page.waitForTimeout(650);
    } else {
      await page.waitForTimeout(650);
    }
    const buf = await page.screenshot();
    // sample 9 pixels
    const { PNG } = require('pngjs');
    const png = PNG.sync.read(buf);
    const pts = [[0.25,0.25],[0.5,0.25],[0.75,0.25],[0.25,0.5],[0.5,0.5],[0.75,0.5],[0.25,0.75],[0.5,0.75],[0.75,0.75]];
    const key = pts.map(([xf,yf])=>{
      const x=Math.floor(png.width*xf); const y=Math.floor(png.height*yf);
      const idx=(png.width*y+x)*4;
      return [png.data[idx],png.data[idx+1],png.data[idx+2],png.data[idx+3]].join(',');
    }).join('|');
    console.log(i, key.slice(0,80));
    return key;
  }
  const keys=[];
  for(let i=1;i<=9;i++) keys.push(await sample(i));
  const uniq = new Set(keys);
  console.log('uniqueKeys', uniq.size);

  await browser.close();
  server.close();
})();
